from h34 import *
M=mcq;F=tf;S=short;N=num
def shares(name,title):
    b=f'<text x="380" y="24" text-anchor="middle" font-size="18" font-weight="bold">{title}</text>'
    # whole, half, quarter
    b+='<rect x="30" y="50" width="200" height="110" fill="#fff3c4" stroke="#333" stroke-width="3"/><text x="130" y="185" text-anchor="middle">1 whole</text>'
    b+='<rect x="280" y="50" width="200" height="110" fill="#fff3c4" stroke="#333" stroke-width="3"/><rect x="280" y="50" width="100" height="110" fill="#f4a261" stroke="#333" stroke-width="3"/><text x="380" y="185" text-anchor="middle">one half (2 halves = 1 whole)</text>'
    b+='<rect x="530" y="50" width="200" height="110" fill="#fff3c4" stroke="#333" stroke-width="3"/><rect x="530" y="50" width="100" height="55" fill="#2a9d8f" stroke="#333" stroke-width="3"/><line x1="630" y1="50" x2="630" y2="160" stroke="#333" stroke-width="3"/><line x1="530" y1="105" x2="730" y2="105" stroke="#333" stroke-width="3"/><text x="630" y="185" text-anchor="middle">one quarter (4 quarters = 1 whole)</text>'
    svgfile(name,760,200,b)
shares('c3-half-quarter.svg','Whole, half and quarter')
chapter(3,'maths','fair-share','Fair Share',
 ('Sharing a paratha','Two children have one paratha and want to share it fairly. If one gets a big piece and the other a small piece, it is not fair. They fold it into two pieces that match exactly, and each gets one half. Then four friends come, and the paratha is cut into four equal parts, called quarters.'),
 [('Halves',['A whole thing can be shared equally between two people. Each share is called a half, and two halves make one whole.','For a share to be a half, the two parts must be exactly equal. If one part is bigger, it is not a half.','We can fold a rectangular sheet in half in more than one way: along the middle from top to bottom, from side to side, or along a diagonal. All the ways give two matching parts.','When part of a chikki has been eaten, look at what is left. It may be less than half, exactly half or more than half of the whole piece.','We say one half. We do not say one out of two.']),
  ('Fair sharing',['Amit shared a mango tree, a lamp and a blanket with his brother by taking the fruit, the night and the winter for himself. That was not fair even though it sounded equal.','Sharing is fair when each person gets the same amount of what is useful.','We can share things in different fair ways. Mangoes can be shared half and half. The tree can be shared by taking turns each year or by sharing its fruit equally.']),
  ('Half and double',['Half and double are partners. 3 is half of 6, and 6 is double of 3.','4 marbles are half of 8 marbles, and 8 marbles are double of 4 marbles.','To find half of a number we share it equally into two. To find double we add the number to itself. Half of 14 is 7 and double of 7 is 14.','On a number line we can see how far a number is from the half or the double. 5 is 2 less than 7, which is half of 14, and 13 is 1 less than 14, which is double of 7.']),
  ('Quarters',['When a whole is shared equally among four people, each share is called a quarter. Four quarters make one whole.','Two quarters together make a half, because the whole is cut in two halves and each half is cut again into two quarters.','Three quarters is a whole with one quarter taken away. We say one quarter, two quarters, three quarters and four quarters.','A quarter of 16 flowers is 4, and half of 16 flowers is 8. Half is double a quarter, because 8 is double of 4.','We can make quarters by folding a paper twice, and the folds can be in different directions as long as the four parts match exactly.'])],
 [('A paratha is cut into two pieces. One is bigger. Are these halves?',[('Halves must be exactly equal parts.','The idea of half is equal sharing.'),('One piece is bigger.','So the parts are not equal.'),('No, they are not halves.','To get halves we must cut into two matching parts.')]),
  ('Lakshanya has 16 flowers and ties a quarter of them. How many does she tie?',[('A quarter means share into 4 equal parts.','Four quarters make a whole.'),('16 ÷ 4 = 4.','Divide the 16 flowers into 4 equal groups.'),('She ties 4 flowers.','Check: 4 groups of 4 is 16.')]),
  ('Half of Peehu\'s 16 flowers are tied. How many tied flowers is that, and how does it compare with a quarter?',[('Half of 16 is 16 ÷ 2 = 8.','Share into 2 equal groups.'),('A quarter of 16 is 4.','Share into 4 equal groups.'),('8 is double of 4.','So half is double a quarter.')])],
 ('Explain what a half and a quarter are and how they are related.',['A half is one of two equal parts','A quarter is one of four equal parts','Two quarters make a half','The parts must be equal'],['Any two pieces can be called halves','A quarter is bigger than a half']),
 ['A half is one of two equal parts, and 2 halves make 1 whole.','A quarter is one of four equal parts, and 4 quarters make 1 whole.','2 quarters are the same as a half.','Half and double are partners, 3 is half of 6.','Fair sharing means equal parts.'],
 [M('1',1,'How many halves make one whole?','2',[('1','1 half is only part'),('4','4 is the number of quarters')],'Two halves make one whole.'),
  M('2',1,'How many quarters make one whole?','4',[('2','2 is the number of halves'),('3','Three quarters is not a whole')],'Four quarters make one whole.'),
  F('3',1,'A half must be one of two equal parts.',True,'Unequal parts cannot be halves.'),
  N('4',1,'Half of 6 is?',3,'6 shared equally in two is 3.',[(12,'That is double of 6'),(2,'That is 6 ÷ 3')]),
  N('5',2,'Double of 7 is?',14,'7 + 7 = 14.',[(3,'That is about half'),(21,'That is 7 × 3')]),
  N('6',2,'A quarter of 16 flowers is?',4,'16 ÷ 4 = 4.',[(8,'That is half of 16'),(12,'That is three quarters')]),
  N('7',2,'Half of 16 flowers is?',8,'16 ÷ 2 = 8.',[(4,'That is a quarter'),(14,'Share equally in two')]),
  M('8',2,'Which equals two quarters?','One half',[('One whole','4 quarters make a whole'),('One quarter','That is only one')],'2 quarters = 1 half.'),
  M('9',2,'Which is bigger?','Half of 8',[('A quarter of 8','A quarter of 8 is 2'),('They are equal','Half of 8 is 4, a quarter is 2')],'Half is bigger than a quarter.'),
  S('10',2,'What is each share called when a whole is shared equally among four people?',['quarter','a quarter','one quarter'],'Four equal parts are quarters.'),
  F('11',3,'Amit\'s way of sharing the mango tree was fair.',False,'He kept the fruit and gave the tree. That was not fair.'),
  M('12',3,'4 marbles are ____ of 8 marbles.','half',[('double','8 is double of 4'),('a quarter','A quarter of 8 is 2')],'Half of 8 is 4.')],
 svgs=[('c3-half-quarter','A whole, a half and a quarter of a rectangle','Equal parts make halves and quarters.')],
 keep=['half','quarter','whole'])
chapter(3,'maths','filling-and-lifting','Filling and Lifting',
 ('Whose glass holds more?','Nita and Monu visit Ritu\'s house and get milk in different glasses. Who gets the most? Ritu\'s sister pours all the milk into three same-sized glasses and then we can see. In this chapter we learn how to find which holds more and which weighs more.'),
 [('Capacity: which holds more?',['The amount a vessel can hold is called its capacity. We can compare two glasses by pouring from one to the other.','If a small glass is filled and poured into a big glass, the big glass does not fill up. So it holds more.','A jug holds more than a glass, and a glass holds more than a ladle. We can use a small vessel as a measure and count how many fill a bigger one.','If 4 glasses fill a jug, then 8 glasses are needed for 2 jugs. The quantity of water stays the same when we pour it into different vessels.']),
  ('The litre',['A litre is a unit that we use to measure how much liquid a vessel holds. Milk is often measured in litres.','A measuring cup is used to give 1 litre of milk, so everybody gets the same amount.','A glass usually holds less than a litre, and a bucket holds more than a litre.','Half a litre is exactly half of a litre, and a quarter litre is one of four equal parts of a litre. Two half-litre mugs make a litre, and four quarter-litre glasses make a litre.','It takes about 5 litres of water to make a single plastic bottle of 1 litre. Using our own bottle saves water.']),
  ('Heavy or light',['Some things are heavier and some are lighter. A pan balance helps to see which is heavier, because the heavier object makes its pan go down.','We can weigh a pencil by balancing it with coins or erasers. A heavier object needs more of them.','A matchbox filled with sand can be used as a weight for slightly heavier things such as a pencil box.','A kilogram is a unit for weight. Sugar and salt are often sold in packets of 1 kilogram. A half-kilogram packet is half as heavy and a quarter-kilogram packet is one of four equal parts.','Two half-kilogram packets balance one 1-kilogram packet on a pan balance.']),
  ('Tricky balls',['Three balls look the same, but one is heavier. We place one ball on each pan, and keep the third aside.','If the pans balance, the ball left aside is the heavy one. If one pan goes down, that pan holds the heavy ball. So one weighing is enough.','To order three balls from lightest to heaviest we compare them two at a time on the pan balance.'])],
 [('Ritu\'s glass fills 3 small bowls. A jug fills 4 glasses. Which holds more, the jug or the glass?',[('One jug needs 4 glasses to fill.','A bigger vessel holds more small ones.'),('So the jug holds more than a glass.','The measure is the glass.')]),
  ('How many half-litre mugs fill a 1-litre bottle?',[('A half litre is half of a litre.','Two halves make a whole.'),('So 2 mugs fill the bottle.','2 × half litre = 1 litre.')]),
  ('One of three balls is heavier. How can we find it with a single weighing?',[('Put one ball on each pan and keep one aside.','Two balls are compared and one is left out.'),('If the pans are level, the ball kept aside is the heavy one.','Equal pans mean the two on the pans are equal.'),('If one pan goes down, that pan holds the heavy ball.','The heavier side goes down.')])],
 ('Explain how you would find which of two glasses holds more.',['Fill one glass','Pour into the other','If it overflows, the first holds more','If there is space left, the first holds less'],['The taller glass always holds more','Weight and capacity mean the same']),
 ['Capacity is how much a vessel can hold.','A litre is a unit for liquid. Two half litres or four quarter litres make a litre.','A pan balance shows which object is heavier, the lower pan.','A kilogram is a unit for weight. Two half kilograms make a kilogram.','One weighing is enough to find the heavier of three balls.'],
 [M('1',1,'What do we call the amount a vessel can hold?','Capacity',[('Weight','Weight tells how heavy'),('Length','Length tells how long')],'Capacity is how much a vessel holds.'),
  M('2',1,'Which side of a pan balance goes down?','The heavier side',[('The lighter side','The lighter side goes up'),('Either side','It depends on the weight')],'The heavier pan goes down.'),
  N('3',1,'How many half-litre mugs make 1 litre?',2,'Two halves make a whole.',[(4,'4 quarters make a litre'),(1,'1 mug is half a litre')]),
  N('4',1,'How many quarter-litre glasses make 1 litre?',4,'Four quarters make a whole.',[(2,'2 halves make a litre'),(3,'3 quarters is not a whole litre')]),
  M('5',2,'Which unit measures how much milk a jug holds?','Litre',[('Kilogram','Kilogram is for weight'),('Metre','Metre is for length')],'We measure liquid in litres.'),
  M('6',2,'Which unit is used for the weight of a packet of salt?','Kilogram',[('Litre','Litre is for liquids'),('Centimetre','That is for length')],'Salt is weighed in kilograms.'),
  N('7',2,'How many half-kilogram packets make 1 kilogram?',2,'Two halves make a whole.',[(4,'That is quarter kilograms'),(1,'One half is not a whole')]),
  F('8',2,'A taller glass always holds more than a shorter one.',False,'A short wide glass may hold more. We must compare by pouring.'),
  N('9',2,'How many glasses are needed to fill 3 jugs if 1 jug fills 4 glasses?',12,'3 × 4 = 12.',[(7,'3 + 4 is 7'),(4,'That is one jug')]),
  M('10',2,'If two pans are level when you weigh two balls, what do you know?','They weigh the same',[('One is heavier','Then one pan would go down'),('Both are empty','They hold balls')],'A level pan balance means equal weight.'),
  S('11',3,'With three balls, one heavier, how many weighings do you need?',['1','one','one weighing'],'Put one ball on each pan and keep one aside.'),
  F('12',3,'Weight and capacity mean the same.',False,'Capacity is how much a vessel holds. Weight is how heavy something is.')],
 keep=['capacity','litre','kilogram'])
